// --- Primitives ---
function box3(x1,y1,z1,x2,y2,z2,t){
  for(let x=Math.min(x1,x2);x<=Math.max(x1,x2);x++)
  for(let y=Math.min(y1,y2);y<=Math.max(y1,y2);y++)
  for(let z=Math.min(z1,z2);z<=Math.max(z1,z2);z++)block(x,y,z,t);
}
function wheel(cx,cy,cz,r,t){
  for(let a=0;a<360;a+=4){let rad=a*Math.PI/180;let px=Math.round(cx+r*Math.cos(rad));let py=Math.round(cy+r*Math.sin(rad));block(px,py,cz,t);block(px,py,cz+1,t);}
  block(cx,cy,cz,t);block(cx,cy,cz+1,t);
  for(let a=0;a<360;a+=90){let rad=a*Math.PI/180;block(Math.round(cx+Math.round(r/2)*Math.cos(rad)),Math.round(cy+Math.round(r/2)*Math.sin(rad)),cz,t);block(Math.round(cx+Math.round(r/2)*Math.cos(rad)),Math.round(cy+Math.round(r/2)*Math.sin(rad)),cz+1,t);}
  for(let a=0;a<360;a+=45){let rad=a*Math.PI/180;block(Math.round(cx+Math.round(r*0.7)*Math.cos(rad)),Math.round(cy+Math.round(r*0.7)*Math.sin(rad)),cz,t);block(Math.round(cx+Math.round(r*0.7)*Math.cos(rad)),Math.round(cy+Math.round(r*0.7)*Math.sin(rad)),cz+1,t);}
}
function dome(x,y,z,r,h,t){
  for(let dy=0;dy<=h;dy++){let rr=Math.max(1,Math.round(r*Math.sqrt(Math.max(0,1-(dy/h)*(dy/h)))));for(let a=0;a<360;a+=6){let rad=a*Math.PI/180;block(Math.round(x+rr*Math.cos(rad)),y+dy,Math.round(z+rr*Math.sin(rad)),t);}}
}
function cone3(x,y,z,r,h,t){
  for(let dy=0;dy<=h;dy++){let frac=dy/h;let rr=Math.max(1,Math.round(r*(1-frac*0.85)));for(let a=0;a<360;a+=6){let rad=a*Math.PI/180;block(Math.round(x+rr*Math.cos(rad)),y+dy,Math.round(z+rr*Math.sin(rad)),t);}}
}
function mounded(x,y,z,r,h,t){
  for(let dy=0;dy<=h;dy++){let frac=dy/h;let rr=Math.round(r*(1-frac*frac*0.5));if(rr<1)rr=1;for(let a=0;a<360;a+=8){let rad=a*Math.PI/180;block(Math.round(x+rr*Math.cos(rad)),y+dy,Math.round(z+rr*Math.sin(rad)),t);}}
}
function ring(cx,cy,cz,r,tube,t){
  for(let a=0;a<360;a+=4){let rad=a*Math.PI/180;let px=Math.round(cx+r*Math.cos(rad));let py=Math.round(cy+r*Math.sin(rad));for(let di=-tube;di<=tube;di++)block(px+di,py+di,cz,t);}
}
function cylinderX(x1,x2,y,z,r,t){
  for(let x=x1;x<=x2;x++)for(let a=0;a<360;a+=4){let rad=a*Math.PI/180;block(x,Math.round(y+r*Math.cos(rad)),Math.round(z+r*Math.sin(rad)),t);}
}
function cylinderZ(x,y1,y2,z,r,t){
  for(let y=y1;y<=y2;y++)for(let a=0;a<360;a+=4){let rad=a*Math.PI/180;block(Math.round(x+r*Math.cos(rad)),y,Math.round(z+r*Math.sin(rad)),t);}
}

