function tree(tx,ty,tz,height){
  // Trunk
  box3(tx,ty,tz,tx,ty+height-1,tz,oak_log);
  if(height>4)box3(tx,ty,tz-1,tx,ty+2,tz+1,oak_log);
  // Canopy (layered spheres for natural look)
  for(let layer=0;layer<3;layer++){
    let cy=ty+height+layer*2-1;
    let cr=3-layer;
    for(let a=0;a<360;a+=10){
      let rad=a*Math.PI/180;
      for(let r2=0;r2<=cr;r2++){
        block(Math.round(tx+r2*Math.cos(rad)),cy,Math.round(tz+r2*Math.sin(rad)),oak_leaves);
        block(Math.round(tx+r2*Math.cos(rad)),cy+1,Math.round(tz+r2*Math.sin(rad)),oak_leaves);
      }
    }
  }
  // Top
  block(tx,ty+height+4,tz,oak_leaves);
  block(tx+1,ty+height+3,tz,oak_leaves);
  block(tx-1,ty+height+3,tz,oak_leaves);
  block(tx,ty+height+3,tz+1,oak_leaves);
  block(tx,ty+height+3,tz-1,oak_leaves);
}
